fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Get dimensions of input matrix
    let num_rows = x.len();
    let num_cols = x[0].len();
    
    // Create output matrix with swapped dimensions
    // The output will have num_cols rows, each with num_rows elements
    let mut result = vec![vec![0.0; num_rows]; num_cols];
    
    // Populate the transposed matrix
    for r in 0..num_rows {
        for c in 0..num_cols {
            result[c][r] = x[r][c];
        }
    }
    
    result
}